GermanWords, strippedGermanWords, EnglishWords = [], [], []
for wordMapEntry in GERMAN_WORD_MAP:
    assert len(wordMapEntry) == 2, f"{wordMapEntry}"
    GermanWord,EnglishWord = wordMapEntry
    assert isinstance( GermanWord, str ) and (len(GermanWord)>=2 or GermanWord in ('J','j')), f"{GermanWord=}"
    assert GermanWord != EnglishWord, f"Attempting to replace identical German word: {GermanWord=}"
    assert GermanWord not in GermanWords, f"duplicate GermanWord: {GermanWord=} ({EnglishWord=})"
    if GermanWord.startswith(' ') or EnglishWord.startswith(' '): assert GermanWord.startswith(' '), f"Mismatched leading space: {GermanWord=} {EnglishWord=}"
    if GermanWord.endswith(' ') or EnglishWord.endswith(' '): assert GermanWord.endswith(' '), f"Mismatched trailing space: {GermanWord=} {EnglishWord=}"
    # assert GermanWord not in EnglishWord, f"Recursive substitution of '{GermanWord}' into '{EnglishWord}'"
    assert '  ' not in GermanWord, f"{GermanWord=} {EnglishWord=}"
    assert 'Æ' not in GermanWord; assert 'æ' not in GermanWord
    assert 'œ' not in GermanWord
    assert not GermanWord.endswith('bus')
    assert not GermanWord.endswith('ci'); assert not GermanWord.endswith('li')
    assert not GermanWord.endswith('cum'); assert not GermanWord.endswith('lum')
    GermanWords.append( GermanWord ); strippedGermanWords.append( GermanWord.strip() )
    if GermanWord.startswith(' '): assert EnglishWord.startswith(' '), f"Mismatched leading space:  {GermanWord=} {EnglishWord=}"
    if GermanWord.endswith(' '): assert EnglishWord.endswith(' '), f"Mismatched trailing space: {GermanWord=} {EnglishWord=}"
    if EnglishWord[-1] in ' ,.:;':
        assert GermanWord[-1] == EnglishWord[-1], f"Mismatched trailing character: {GermanWord=} {EnglishWord=}"
    if GermanWord[-1] in ' ,.:;':
        assert EnglishWord[-1] == GermanWord[-1], f"Mismatched trailing character: {GermanWord=} {EnglishWord=}"
    assert '  ' not in EnglishWord
    if ' ' not in GermanWord.strip():
        assert ' ' not in EnglishWord.strip(), f"Space in middle of {EnglishWord=}" # No space in middle
    EnglishWords.append( EnglishWord )
del GermanWords, EnglishWords # strippedGermanWords are used below

def translateGerman( htmlStr:str ) -> str:
    """
    Do basic word-for-word translation from Luther's German Bible to English.

    Text in htmlStr parameter can be inside a span,
        e.g., '<span class="Wycl_verseTextChunk">ech man in his seruice, and in the offring,</span>'
    """
    fnPrint( DEBUGGING_THIS_MODULE, f"translateGerman( ({len(htmlStr)}) )" )

    # if html.startswith( 'und '): # Handle common exception that can't be expressed in the word table
    #     html = f'and {html[4:]}'
    htmlStr = htmlStr.replace( '»', '‘' ).replace( '«', '’' )
    for GermanWord,EnglishWord in GERMAN_WORD_MAP:
        htmlStr = htmlStr.replace( GermanWord, EnglishWord )
        if GermanWord[0] == ' ':
            if htmlStr.startswith( GermanWord[1:] ):
                htmlStr = htmlStr.replace( GermanWord[1:], EnglishWord[1:], 1 )
            htmlStr = htmlStr.replace( f'>{GermanWord[1:]}', f'>{EnglishWord[1:]}' )

    return ( htmlStr.replace('joke','j_o_k_e') # Protect this word because of yoke
                .replace('j','y').replace('J','Y') # Try to write it like it might have sounded
                # But then need to fix up some regular English words
                .replace('conyur','conjur')
                .replace('eyect','eject') # deject and eject
                .replace('inyur','injur')
                .replace('mayestic','majestic')
                .replace('yew','jew') # jewel
                .replace('/yob','/job')
                .replace('y_o_k_e','joke')
                .replace('yoy','joy')
                .replace('eyoice','ejoice')
                .replace('yaguar','jaguar')
                .replace('yail','jail')
                .replace('yudg','judg')
                .replace('yump','jump')
                .replace('yuniper','juniper')
                .replace('yust','just')
                .replace('subyect','subject')
                .replace('(ay)','(aj)')
            )
# end of EuropeanToEnglish.translateGerman


